        code = {2: "AICORE_NOT_FOUND", 3: "BRIDGE_PARTNER_UNAVAILABLE"}.get(stop.code, "PLUGIN_FAILED")
        reply(request_id, "error", error={"code": code, "message": f"{code}: see the plugin's stderr"})
    except Blocked as blocked:
